def make_plotly_div(div_id, chart_spec):
    if 'data' in chart_spec:
        traces = chart_spec['data']
        layout = {
            'title': {'text': chart_spec.get('title', ''), 'font': {'size': 14, 'family': 'Inter, sans-serif'}},
            'barmode': chart_spec.get('barmode', 'group'),
            'margin': {'t': 40, 'b': 40, 'l': 60, 'r': 20},
            'paper_bgcolor': 'rgba(0,0,0,0)',
            'plot_bgcolor': 'rgba(0,0,0,0)',
            'font': {'family': 'Inter, sans-serif'},
            'yaxis': {'gridcolor': '#e5e7eb'},
            'xaxis': {'gridcolor': '#e5e7eb'},
        }
    else:
        traces = [{
            'x': chart_spec.get('x', []),
            'y': chart_spec.get('y', []),
            'type': chart_spec.get('type', 'bar'),
            'orientation': chart_spec.get('orientation', 'v'),
            'marker': chart_spec.get('marker', {'color': '#2563eb'}),
            'name': chart_spec.get('title', '')
        }]
        layout = {
            'title': {'text': chart_spec.get('title', ''), 'font': {'size': 14, 'family': 'Inter, sans-serif'}},
            'margin': {'t': 40, 'b': 40, 'l': 60 if chart_spec.get('orientation') == 'h' else 40, 'r': 20},
            'paper_bgcolor': 'rgba(0,0,0,0)',
            'plot_bgcolor': 'rgba(0,0,0,0)',
            'font': {'family': 'Inter, sans-serif'},
            'yaxis': {'gridcolor': '#e5e7eb'},
            'xaxis': {'gridcolor': '#e5e7eb'},
        }
    traces_json = json.dumps(traces)
    layout_json = json.dumps(layout)
    # Use string concatenation to avoid f-string brace conflicts
    return '\n    <div id="' + div_id + '" style="width:100%;height:350px;"></div>\n    <script>\n        Plotly.newPlot(\'' + div_id + '\', ' + traces_json + ', ' + layout_json + ', {responsive: true});\n    </script>\n    '

